from pathlib import Path
import yaml,json,copy,hashlib
w=Path('/private/tmp/aigr-nitrogen-pts-taxon-audit');p=w/'genes/BACSU/ptsH/ptsH-ai-review.yaml';c=w/'analysis/module_audits/bacterial_nitrogen_regulatory_pts/control-reviews-20261107';d=yaml.safe_load(p.read_text());assert all(a['review']['action']=='PENDING' for a in d['existing_annotations'])
