baseline=[payload(a) for a in d['existing_annotations']];raw={str(f.relative_to(w)):hashlib.sha256(f.read_bytes()).hexdigest() for f in p.parent.glob('*') if f.name.endswith(('-uniprot.txt','-goa.tsv'))}
def support(ref,quote):return {'reference_id':ref,'supporting_text':quote}
u='file:BACSU/ptsH/ptsH-uniprot.txt'
reviews=[
 {'action':'REMOVE','summary':'The interaction evidence is retained, but bare protein binding is uninformative.','reason':'Apply the repository exception for GO:0005515; this is not a claim that the curated CcpA interaction is false. The cached network-paper abstract does not enumerate the HPr edge, so it cannot independently establish the particular assay. The CcpA interaction is independently supported by target biochemistry and retained in the transcription-corepressor synthesis.','supported_by':[support('PMID:8596444','purified CcpA protein\ninteracted with P-ser-HPr')]},
 {'action':'REMOVE','summary':'CcpA-HPr association is real, but generic protein binding does not capture its regulatory role.','reason':'The target study detects CcpA-HPr complexes, especially in glucose-grown cells. Remove the uninformative binding term under the protein-binding policy while retaining the specific phosphostate-dependent corepressor function. This does not reject the experimental annotation or confuse HPr with Crh.','supported_by':[support('PMID:22512862','CcpA-HPr and CcpA-CodY complexes\noccurred only or predominantly in cultures with glucose')]},
 {'action':'ACCEPT','summary':'HPr acts as a soluble cytoplasmic phosphocarrier and regulatory cofactor.','reason':'The curated UniProt localization agrees with the soluble PTS relay and CcpA-cofactor roles. No target subcellular imaging or fractionation is claimed here, and the source does not establish a finer anatomical location. Retain cytoplasm at the supported granularity.','supported_by':[support(u,'SUBCELLULAR LOCATION: Cytoplasm.')]},
 {'action':'ACCEPT','summary':'HPr participates directly in the carbohydrate PTS by relaying phosphate from enzyme I to EIIA.','reason':'This is a genuine carbohydrate-PTS carrier, despite its PANTHER SF2 name mentioning NPr. The native HPr His15 active site and curated transfer to sugar-PTS EIIA corroborate the inherited process claim. PAINT is an ancestral-node judgment; the decision rests on native function rather than donor count. This does not establish a nitrogen-regulatory PtsP-PtsN relay in Bacillus.','supported_by':[support(u,'Phospho-HPr then transfers it to the PTS EIIA\nCC       domain.'),support('PMID:1549615','active-site histidine, His-15')]},
 {'action':'ACCEPT','summary':'Ser46-dependent HPr regulation of carbohydrate utilization is a core role.','reason':'The original mutation and reversion experiments support carbon-catabolite regulation. Independent footprinting shows the molecular contribution: seryl-phosphorylated HPr associates with CcpA in a complex recognizing a catabolite-responsive DNA element. This is regulatory participation, rather than merely a growth phenotype. The exact process term covers both repression and the condition-dependent differences among tested catabolic genes.','supported_by':[support('PMID:8195089','expression of gluconate\nkinase and glucitol dehydrogenase regained full sensitivity to repression by PTS\nsugars.')]}
]
for a,r in zip(d['existing_annotations'],reviews):a['review']=r
d['description']='HPr is a soluble phosphocarrier of the Bacillus subtilis carbohydrate phosphotransferase system. It relays phosphate through His15 from enzyme I to sugar-specific EIIA proteins. A separate phosphorylation at Ser46 converts HPr into a CcpA-associated transcriptional corepressor, linking preferred-carbon availability to catabolite repression.'
for pmid,statement in [('8596444','Purified CcpA and seryl-phosphorylated HPr form a complex that specifically protects the gnt catabolite-responsive element in footprinting experiments.'),('1549615','The native HPr structure identifies His15 at the catalytic site; the detailed phosphoryl-transfer geometry is a structural model, not a new target kinetic measurement.')]:
 s=(w/f'publications/PMID_{pmid}.md').read_text();meta=yaml.safe_load(s.split('---',2)[1]);d['references'].append({'id':'PMID:'+pmid,'title':meta['title'],'findings':[{'statement':statement}]})
d['references'].append({'id':u,'title':'UniProtKB P08877: Bacillus subtilis HPr','findings':[{'statement':'Curated functional text distinguishes the carbohydrate phosphocarrier role from the Ser46-dependent CcpA corepressor role. The PTHR33705:SF2 classification is genuine but does not make this protein a nitrogen-relay NPr.'}]})
for r in d['references']:
 if r['id']=='PMID:8195089':r['findings']=[{'statement':'Ser46 substitution and reversion alter catabolite repression of multiple native catabolic activities, with different responses among the tested genes.'}]
 if r['id']=='PMID:22512862':r['findings']=[{'statement':'Glucose-associated CcpA-HPr complexes support the regulatory partner relationship; the reported surface-plasmon resonance experiments for other CcpA partners are not reassigned to HPr.'}]
d['core_functions']=[
 {'description':'Transfers a phosphoryl group through His15 to histidyl acceptors on sugar-PTS EIIA proteins, linking enzyme-I phosphorylation to carbohydrate uptake.','molecular_function':{'id':'GO:0016775','label':'phosphotransferase activity, nitrogenous group as acceptor'},'directly_involved_in':[{'id':'GO:0009401','label':'phosphoenolpyruvate-dependent sugar phosphotransferase system'}],'locations':[{'id':'GO:0005737','label':'cytoplasm'}],'supported_by':[support(u,'Phospho-HPr then transfers it to the PTS EIIA\nCC       domain.')]},
 {'description':'Seryl-phosphorylated HPr acts with the DNA-binding regulator CcpA as a transcriptional corepressor at catabolite-responsive elements. HPr is the cofactor, not the sequence-specific DNA-binding subunit.','molecular_function':{'id':'GO:0003714','label':'transcription corepressor activity'},'directly_involved_in':[{'id':'GO:0043610','label':'regulation of carbohydrate utilization'}],'locations':[{'id':'GO:0005737','label':'cytoplasm'}],'supported_by':[support('PMID:8596444','specific protection of the gnt CRE against\nDNase I digestion.')]}]
